    pub async fn list_active_task_execution_authorities(
        &self,
        after_task_id: Option<&str>,
        limit: u64,
    ) -> Result<Vec<ActiveTaskExecutionAuthorityRecord>> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        let rows = self
            .connection
            .query_all_raw(Statement::from_sql_and_values(
                self.connection.get_database_backend(),
                "SELECT t.id AS task_id, t.workspace_id AS task_workspace_id, \
                        a.workspace_id AS admission_workspace_id, \
                        a.root_thread_id, a.initiating_principal_id, \
                        a.authorization_context_json, \
                        root.workspace_id AS root_thread_workspace_id, \
                        root.access_class AS root_thread_access_class, \
                        gp.id AS principal_id, gp.kind AS principal_kind \
                 FROM task t \
                 LEFT JOIN task_execution_admission a ON a.task_id = t.id \
                 LEFT JOIN \"thread\" root ON root.id = a.root_thread_id \
                 LEFT JOIN gateway_principal gp ON gp.id = a.initiating_principal_id \
                 WHERE t.executor_kind = 'agent' \
                   AND t.status NOT IN ('completed', 'failed', 'blocked', 'cancelled') \
                   AND t.id > ? \
                 ORDER BY t.id ASC LIMIT ?"
                    .to_owned(),
                [
                    after_task_id.unwrap_or_default().into(),
                    i64::try_from(limit).unwrap_or(i64::MAX).into(),
                ],
            ))
            .await
            .context("failed to list active Task execution authority envelopes")?;
        rows.into_iter()
            .map(|row| {
                Ok(ActiveTaskExecutionAuthorityRecord {
                    task_id: row.try_get("", "task_id")?,
                    task_workspace_id: row.try_get("", "task_workspace_id")?,
                    admission_workspace_id: row.try_get("", "admission_workspace_id")?,
                    root_thread_id: row.try_get("", "root_thread_id")?,
                    initiating_principal_id: row.try_get("", "initiating_principal_id")?,
                    authority_envelope_json: row
                        .try_get::<Option<String>>("", "authorization_context_json")?
                        .filter(|json| !json.trim().is_empty()),
                    root_thread_workspace_id: row.try_get("", "root_thread_workspace_id")?,
                    root_thread_access_class: row.try_get("", "root_thread_access_class")?,
                    principal_id: row.try_get("", "principal_id")?,
                    principal_kind: row.try_get("", "principal_kind")?,
                })
            })
            .collect()
    }

    pub async fn claim_due_turn_event_deliveries(
        &self,
        consumer: &str,
        now_unix: i64,
        limit: u64,
    ) -> Result<Vec<ClaimedTurnEventDeliveryRecord>> {
        let consumer = consumer.to_owned();
        self.run_serialized_write(|| {
            let consumer = consumer.clone();
            async move {
                let now = unix_to_datetime(now_unix);
                let claim_expires_at = unix_to_datetime(now_unix.saturating_add(120));
                let claimed = turn_event_delivery::claim_due(
                    &self.connection,
                    consumer.as_str(),
                    now,
                    claim_expires_at,
                    limit,
                )
                .await?;
                let mut records = Vec::with_capacity(claimed.len());
                for claim in claimed {
                    let event =
                        turn_event::find_event_by_id(&self.connection, claim.row.event_id.as_str())
                            .await?
                            .with_context(|| {
                                format!(
                                    "turn event `{}` is missing for delivery `{}`",
                                    claim.row.event_id, claim.row.id
                                )
                            })?;
                    records.push(ClaimedTurnEventDeliveryRecord {
                        id: claim.row.id,
                        consumer: claim.row.consumer,
                        attempt_count: claim.row.attempt_count,
                        claim_token: claim.claim_token,
                        event,
                    });
                }
                Ok(records)
            }
        })
        .await
    }

    pub async fn complete_turn_event_delivery(
        &self,
        id: &str,
        claim_token: &str,
        now_unix: i64,
    ) -> Result<bool> {
        let id = id.to_owned();
        let claim_token = claim_token.to_owned();
        self.run_serialized_write(|| async {
            turn_event_delivery::mark_delivered(
                &self.connection,
                id.as_str(),
                claim_token.as_str(),
                unix_to_datetime(now_unix),
            )
            .await
        })
        .await
    }

    pub async fn fail_turn_event_delivery(
        &self,
        id: &str,
        claim_token: &str,
        attempt_count: i64,
        error: String,
        now_unix: i64,
    ) -> Result<bool> {
        let id = id.to_owned();
        let claim_token = claim_token.to_owned();
        self.run_serialized_write(|| {
            let error = error.clone();
            let id = id.clone();
            let claim_token = claim_token.clone();
            async move {
                const MAX_ATTEMPTS: i64 = 10;
                let exhausted = attempt_count.saturating_add(1) >= MAX_ATTEMPTS;
                let exponent = u32::try_from(attempt_count.clamp(0, 8)).unwrap_or(8);
                let delay = 2_i64.saturating_pow(exponent).min(300);
                turn_event_delivery::mark_failed(
                    &self.connection,
                    id.as_str(),
                    claim_token.as_str(),
                    error,
                    unix_to_datetime(now_unix.saturating_add(delay)),
                    unix_to_datetime(now_unix),
                    exhausted,
                )
                .await
            }
        })
        .await
    }

