    pub async fn get_turn(&self, thread_id: &str, turn_id: &str) -> Result<Option<(String, Turn)>> {
        let Some(thread_model) = thread::find_thread_by_id(&self.connection, thread_id).await?
        else {
            return Ok(None);
        };

        let Some(turn_model) =
            turn::find_turn_by_thread_and_id(&self.connection, thread_id, turn_id).await?
        else {
            return Ok(None);
        };

        let Some(status) = turn_status_from_db(turn_model.status.as_str()) else {
            return Ok(None);
        };

        let prompt_manifest = parse_turn_prompt_manifest(&turn_model)?;
        let permission_profile = parse_turn_permission_profile(&turn_model)?;
        let collaboration = turn::collaboration_from_model(&turn_model)?;

        Ok(Some((
            thread_model.workspace_id,
            Turn {
                id: turn_model.id,
                status,
                turn_kind: turn_kind_from_db(turn_model.turn_kind.as_str()).unwrap_or_default(),
                origin: turn_origin_from_db(turn_model.origin.as_str()).unwrap_or_default(),
                mode: collaboration.mode.effective_mode,
                author: collaboration.author,
                reply_to_turn_id: collaboration.reply_to_turn_id,
                mentions: collaboration.mentions,
                message_revision: collaboration.message_revision,
                message_deleted: collaboration.message_deleted,
                error: turn_model.error,
                prompt_manifest,
                permission_profile,
            },
        )))
    }

    pub async fn get_turns_by_thread_and_ids(
        &self,
        thread_id: &str,
        turn_ids: &[String],
    ) -> Result<HashMap<String, Turn>> {
        let rows =
            turn::find_turns_by_thread_and_ids(&self.connection, thread_id, turn_ids).await?;
        rows.into_iter()
            .filter_map(|row| match thread_snapshot_turn_from_db_model(row) {
                Ok(Some(turn)) => Some(Ok((turn.id.clone(), turn))),
                Ok(None) => None,
                Err(error) => Some(Err(error)),
            })
            .collect()
    }

    pub async fn complete_in_progress_turns_after_final_agent_message(
        &self,
        event_timestamp_secs: i64,
    ) -> Result<u64> {
        let turns = pioneer_entity::turn::Entity::find()
            .filter(
                pioneer_entity::turn::Column::Status.eq(turn_status_to_db(TurnStatus::InProgress)),
            )
            .all(&self.connection)
            .await
            .context("failed to query in-progress turns for final-agent-message repair")?;

        let mut completed = 0u64;
        for turn_model in turns {
            let Some(latest_event) =
                turn_event::latest_event_for_turn(&self.connection, turn_model.id.as_str()).await?
            else {
                continue;
            };
            let TurnEventPayload::ItemCompleted(notification) = latest_event.payload else {
                continue;
            };
            if !matches!(&notification.item, TurnItem::AgentMessage { .. }) {
                continue;
            }
            let Some(thread_model) =
                thread::find_thread_by_id(&self.connection, turn_model.thread_id.as_str()).await?
            else {
                continue;
            };

            let prompt_manifest = parse_turn_prompt_manifest(&turn_model)?;
            let permission_profile = parse_turn_permission_profile(&turn_model)?;
            let collaboration = turn::collaboration_from_model(&turn_model)?;
            self.materialize_turn_completed(
                pioneer_protocol::TurnCompletedNotification {
                    workspace_id: thread_model.workspace_id,
                    thread_id: turn_model.thread_id.clone(),
                    turn: Turn {
                        id: turn_model.id,
                        status: TurnStatus::Completed,
                        turn_kind: turn_kind_from_db(turn_model.turn_kind.as_str())
                            .unwrap_or_default(),
                        origin: turn_origin_from_db(turn_model.origin.as_str()).unwrap_or_default(),
                        mode: collaboration.mode.effective_mode,
                        author: collaboration.author,
                        reply_to_turn_id: collaboration.reply_to_turn_id,
                        mentions: collaboration.mentions,
                        message_revision: collaboration.message_revision,
                        message_deleted: collaboration.message_deleted,
                        error: None,
                        prompt_manifest,
                        permission_profile,
                    },
                },
                event_timestamp_secs,
            )
            .await
            .with_context(|| {
                format!(
                    "failed to materialize completion repair for turn `{}`",
                    notification.turn_id
                )
            })?;
            completed = completed.saturating_add(1);
        }

        Ok(completed)
    }

    pub async fn reconcile_thread_foreground_statuses(
        &self,
        event_timestamp_secs: i64,
    ) -> Result<u64> {
        let active_conversation_thread_ids = pioneer_entity::turn::Entity::find()
            .filter(
                pioneer_entity::turn::Column::Status.eq(turn_status_to_db(TurnStatus::InProgress)),
            )
            .filter(
                pioneer_entity::turn::Column::TurnKind.eq(turn_kind_to_db(TurnKind::Conversation)),
            )
            .all(&self.connection)
            .await
            .context("failed to query in-progress conversation turns for status repair")?
            .into_iter()
            .map(|turn| turn.thread_id)
            .collect::<HashSet<_>>();
        let threads = pioneer_entity::thread::Entity::find()
            .all(&self.connection)
            .await
            .context("failed to query threads for foreground status repair")?;
        let updated_at = unix_to_datetime(event_timestamp_secs);
        let mut repaired = 0u64;

        for thread_model in threads {
            let desired = if active_conversation_thread_ids.contains(thread_model.id.as_str()) {
                ThreadStatus::Active
            } else {
                ThreadStatus::Idle
            };
            let Some(current) = thread_status_from_db(thread_model.status.as_str()) else {
                continue;
            };
            if current == desired {
                continue;
            }
            repositories::thread::update_thread_status(
                &self.connection,
                thread_model.id.as_str(),
                desired,
                updated_at,
            )
            .await?;
            repaired = repaired.saturating_add(1);
        }

        Ok(repaired)
    }

